const lead = $json;
const msg = $('Outlook: no leídos').item.json;
if (!lead || !lead.ID_Lead) return [];
const hoy = $now.toFormat('yyyy-LL-dd');
const texto = (msg.body && msg.body.content) ? msg.body.content : (msg.bodyPreview||'');
const system = [
'<identidad>Agente de ACCES GROUP (Ricardo Varela) manejando la respuesta de un prospecto. Consultiva, sin presion, sin precio prematuro, sin inventar.</identidad>',
'<frontera>Fabricamos y calificamos hasta el 1er contacto. Si el prospecto responde con requerimiento/inquietud real -> LEAD, nuevo_estado=lead_handoff (sale a comercial). Reunion aceptada != trato ganado.</frontera>',
'<candado>Ninguna cuenta a lead_handoff sin Economic Buyer mapeado. Si revelan quien decide, decisor_revelado=true + nombre. Si el que responde no decide y no da al decisor -> correo de orientacion.</candado>',
'<intenciones>interesado_agenda | requerimiento | pregunta | objecion | no_interesado | fuera_de_oficina | dio_decisor | otro</intenciones>',
'<reglas>Espanol, max ~120 palabras, 1 CTA, sin firma. objecion: escuchar-reconocer-pregunta de diagnostico, NO descuentes, NO presiones (reactivacion si es precio). no_interesado: agradece y cierra (nurturing). fuera_de_oficina: no redactes, reprograma.</reglas>',
'<agenda>Si interesado_agenda: decision_agenda=true, 2 franjas ISO horario laboral (evita 13-14h), zona America/Mexico_City.</agenda>',
'<salida>SOLO este JSON sin ``` : {"intencion":"","decisor_revelado":false,"decisor_nombre":"","nuevo_score":0,"nuevo_estado":"respondio|agendado|lead_handoff|nurturing|descartado","nueva_etapa":"Primer contacto|Handoff comercial","decision_agenda":false,"propuesta_reunion":{"titulo":"","duracion_min":20,"opciones":[]},"asunto_respuesta":"","cuerpo_html":"","fecha_siguiente_paso":"YYYY-MM-DD","razon":""}</salida>'
].join('\n');
const user = `Fecha hoy: ${hoy}\nLead: ${lead.Empresa} — ${lead.Contacto} (${lead.Cargo}) | Micro-ICP: ${lead.Micro_ICP}\nEtapa: ${lead.Etapa} | Score: ${lead.Score_ICP} | Decisor mapeado: ${lead.Decisor_Mapeado}\nAsunto enviado: ${lead.Asunto}\n\nRespuesta del prospecto:\n"""\n${texto}\n"""\n\nClasifica y redacta. Devuelve solo el JSON.`;
return [{ json: { ...lead, msg_id: msg.id, conversationId: msg.conversationId, system, user, hoy } }];

const FIRMA = '<br><br><table cellpadding="0" cellspacing="0" style="font-family:Arial,sans-serif;font-size:13px;color:#333"><tr><td style="padding-top:12px;border-top:2px solid #0a3d62"><strong style="color:#0a3d62">Ricardo Varela</strong><br><span style="color:#555">ACCES GROUP</span><br><a href="mailto:rvarela@accesgroup.com.mx" style="color:#0a3d62">rvarela@accesgroup.com.mx</a></td></tr></table>';
const resp=$json; let text='';
try { text = resp.content[0].text; } catch(e){ text = resp.body ? resp.body.content[0].text : '{}'; }
text = text.replace(/^```json/i,'').replace(/```$/,'').trim();
const d = JSON.parse(text);
const l = $('Prep clasificación').item.json;
d.cuerpo_final = (d.cuerpo_html||'') + FIRMA;
const pr = d.propuesta_reunion || {};
const opt = (pr.opciones && pr.opciones[0]) ? pr.opciones[0] : null;
const dur = pr.duracion_min || 20;
d.reunion_titulo = pr.titulo || ('ACCES GROUP <> ' + (l.Empresa||''));
if (opt) { d.reunion_inicio = opt; d.reunion_fin = new Date(new Date(opt).getTime()+dur*60000).toISOString().slice(0,19); }
if (d.decisor_revelado) d.Decisor_Mapeado = 'si';
return [{ json: { ...l, ...d } }];
